-- Normalise the vato uniqueness rule. An earlier revision created a PARTIAL
-- unique index (WHERE reference <> ''), which ON CONFLICT cannot infer, so both
-- this seed and the admin import would fail. Replace it with a plain unique
-- index and represent "no citation" as NULL. Safe to run either way.
ALTER TABLE public.vato ALTER COLUMN reference DROP NOT NULL;
ALTER TABLE public.vato ALTER COLUMN reference DROP DEFAULT;
UPDATE public.vato SET reference = NULL WHERE reference = '';
DROP INDEX IF EXISTS public.vato_reference_key;
CREATE UNIQUE INDEX vato_reference_key ON public.vato(reference);

-- Swamini Vato 1/1 - 1/50, English translation.
--
-- Transcribed from the BAPS published translation supplied by the app owner.
-- Superscript footnote markers are stripped and footnote bodies omitted, so
-- each row holds the passage exactly as published. No text is paraphrased.
--
-- ON CONFLICT keeps this re-runnable and preserves any edit made through the
-- admin screen: an existing reference is left untouched.

ON CONFLICT (reference) DO NOTHING;
